"""Break list into fixed, n-sized chunks. The final element of the new list will be n-sized or less"""
def chunkFx(mylist: Any, n: Any) -> object {
    chunks = [];
    for i in range(0, len(mylist), n) {
        chunks.append(mylist[i:(i + n)]);
    }
    return chunks;
}

